steps.run:
$manifest = Get-Content pubspec.yaml -Raw
$appVersion = [regex]::Match($manifest, '(?m)^version:\s*(\d+\.\d+\.\d+)').Groups[1].Value
if (-not $appVersion) { throw 'Missing application version' }
$runnerExe = Get-ChildItem build/windows/x64/runner/Release/*.exe | Select-Object -First 1
if (-not $runnerExe) { throw 'Missing Windows runner executable' }
$runnerBytes = [System.IO.File]::ReadAllBytes($runnerExe.FullName)
$peOffset = [BitConverter]::ToInt32($runnerBytes, 0x3c)
if ([BitConverter]::ToUInt16($runnerBytes, $peOffset + 4) -ne 0x8664) { throw 'Windows runner is not x64' }
iscc "/DMyAppVersion=$appVersion" windows/installer/setup.iss
if ($LASTEXITCODE -ne 0) { throw 'Inno Setup compilation failed' }
$installer = Get-Item "$env:GITHUB_WORKSPACE/flutter_forge-setup-x64.exe"
if ($installer.VersionInfo.ProductVersion -notlike "$appVersion*") {
  throw "Installer version mismatch: $($installer.VersionInfo.ProductVersion)"
}
Write-Output "Installer version verified: $($installer.VersionInfo.ProductVersion)"

mkdir -p verified-release
APP_VERSION="$(node tool/release_metadata.js version)"
case "$RELEASE_PLATFORM" in
  macos) cp release-assets/*.dmg "verified-release/FlutterForge-${APP_VERSION}-macos-x64.dmg" ;;
  windows) cp flutter_forge-setup-x64.exe "verified-release/FlutterForge-${APP_VERSION}-windows-x64.exe" ;;
  android) unzip -l apps/flutter_forge/release-assets/*.apk | grep -q "lib/arm64-v8a/"; cp apps/flutter_forge/release-assets/*.apk "verified-release/FlutterForge-${APP_VERSION}-android-arm64-v8a-debug.apk" ;;
  web) (cd apps/flutter_forge/build/web && zip -qr "$GITHUB_WORKSPACE/verified-release/FlutterForge-${APP_VERSION}-web.zip" .) ;;
esac
node tool/release_metadata.js stage verified-release
